bicepWiring.disableAccessKeys:
properties: {
  sku: { name: skuName, family: skuFamily, capacity: skuCapacity }
  enableNonSslPort: false
  minimumTlsVersion: '1.2'
  redisConfiguration: { 'aad-enabled': 'true' }
  disableAccessKeyAuthentication: true
}

sdkInitPattern.typescript:
import Redis from 'ioredis';
import { DefaultAzureCredential } from '@azure/identity';

const credential = new DefaultAzureCredential();
const token = await credential.getToken('https://redis.azure.com/.default');

const client = new Redis({
  host: process.env.AZURE_REDIS_HOST!,
  port: 6380,
  username: process.env.AZURE_CLIENT_ID,
  password: token.token,
  tls: { servername: process.env.AZURE_REDIS_HOST }
});
